import{_ as l,a0 as a,w as i,s as d,I as r,x as s,a1 as p,A as n,ao as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const S=JSON.parse('{"title":"开源软件安全吗？ | LCTT x X-CMD","titleTemplate":false,"description":"开源软件安全吗？ | LCTT (202301) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"开源软件安全吗？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"开源软件安全吗？ | LCTT (202301) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202301/20210718 Is Open-Source Software Secure","title":"开源软件安全吗？","tag":"202301","desc":""},"relativePath":"202301/20210718 Is Open-Source Software Secure.md","filePath":"[post].md"}'),u={name:"202301/20210718 Is Open-Source Software Secure.md"};function f(m,t,g,T,b,x){const e=a("Link");return i(),d("div",null,[t[30]||(t[30]=r("h1",{id:"开源软件安全吗",tabindex:"-1"},[s("开源软件安全吗？ "),r("a",{class:"header-anchor",href:"#开源软件安全吗","aria-label":"Permalink to “开源软件安全吗？”"},"​")],-1)),t[31]||(t[31]=r("p",null,[r("img",{src:"https://news.itsfoss.com/content/images/size/w2000/wordpress/2021/07/open-source-security.jpg",alt:""})],-1)),r("p",null,[t[1]||(t[1]=s("作为一个偏爱 ",-1)),p(e,{href:"https://news.itsfoss.com/linux-foundation-linux-desktop/"},{default:n(()=>[...t[0]||(t[0]=[s("在桌面电脑上使用 Linux",-1)])]),_:1}),t[2]||(t[2]=s("，并鼓励使用开源软件的人，你可能期待就标题中提出的问题得到一个响亮的",-1)),t[3]||(t[3]=r("strong",null,"肯定",-1)),t[4]||(t[4]=s("回答。",-1))]),t[32]||(t[32]=r("p",null,"然而，我并不打算仅限于讨论开源软件的优点。让我们一起探索更多观点！",-1)),t[33]||(t[33]=r("p",null,"在本文，我计划分享我关于开源软件是否安全的思考，以及哪些事情与开源软件的安全性相关。",-1)),t[34]||(t[34]=r("h3",{id:"为什么你需要关注开源软件是否安全",tabindex:"-1"},[s("为什么你需要关注开源软件是否安全？ "),r("a",{class:"header-anchor",href:"#为什么你需要关注开源软件是否安全","aria-label":"Permalink to “为什么你需要关注开源软件是否安全？”"},"​")],-1)),r("p",null,[t[6]||(t[6]=s("不论你是使用 ",-1)),p(e,{href:"https://itsfoss.com/what-is-linux-distribution/"},{default:n(()=>[...t[5]||(t[5]=[s("Linux",-1)])]),_:1}),t[7]||(t[7]=s(" 系统还是使用其他类型的操作系统，你都会在某种程度上（直接地/间接地）被开源软件所包围。",-1))]),t[35]||(t[35]=o('<p>举个例子，大多数专有软件工具依赖于某种形式的开源库来保证其正常工作。</p><p>此外，各种规模的公司（包括谷歌、微软和 Facebook）依赖开源软件或者以某种途径向开源社区贡献资源是有原因的。</p><p>因此，开源软件的安全性是有必要了解的。</p><h3 id="有关开源软件安全性的迷思" tabindex="-1">有关开源软件安全性的迷思 <a class="header-anchor" href="#有关开源软件安全性的迷思" aria-label="Permalink to “有关开源软件安全性的迷思”">​</a></h3><p><img src="https://news.itsfoss.com/content/images/wordpress/2021/07/hacker-exploit-illustration.png" alt=""></p><p>虽然有多种理由证明开源软件在安全性方面的缺陷，然而其中一些实际毫无意义。</p><h4 id="任何人都可以查看并恶意利用开源软件代码" tabindex="-1">任何人都可以查看并恶意利用开源软件代码 <a class="header-anchor" href="#任何人都可以查看并恶意利用开源软件代码" aria-label="Permalink to “任何人都可以查看并恶意利用开源软件代码”">​</a></h4><p>是的，开源软件代码对于任何人都是可访问的。但是你可以查看代码并不意味着你可以利用它。</p><p><strong>不现实。</strong></p><p>即使任何人都可以复刻（或者拷贝）该软件，原始软件也不能轻易地被修改使用。</p><p>通常，项目维护人员（或者维护团队）管理代码仓库，并且接受来自贡献者的提交。开源软件代码在接受之前会被审查。没有人可以就这样劫持代码。</p><p><strong>不论是开源软件还是闭源软件，攻击者都需要付出努力来利用软件中的代码漏洞或者添加恶意代码。</strong></p><h4 id="没有专职团队-安全性无从谈起" tabindex="-1">没有专职团队，安全性无从谈起 <a class="header-anchor" href="#没有专职团队-安全性无从谈起" aria-label="Permalink to “没有专职团队，安全性无从谈起”">​</a></h4><p>很多人相信如果开源软件没有专职人员或者专职团队，维护软件安全性是困难的。</p><p>恰恰相反，由于各种各样类型的贡献者的加入与离开，开源软件获得了来自更大范围的开发者的更多关注。</p><p>他们可能比由专有软件所聘用的少数开发者更能够发现安全问题。</p><p>一些来自 Mozilla 等同类公司的项目拥有自己的专职团队来高效处理安全问题。同样的，大部分成功的开源项目拥有大量的资源用于保障安全性。</p><p>因此，开源软件的生态系统是安全性的组合包。即使没有专职团队，开源项目也可以得到来自各类贡献者的帮助，他们中的一些很大程度上是有利可图的，这有助于他们投入更多的精力。</p><h3 id="开源软件是安全的-以下是原因" tabindex="-1">开源软件是安全的，以下是原因 <a class="header-anchor" href="#开源软件是安全的-以下是原因" aria-label="Permalink to “开源软件是安全的，以下是原因”">​</a></h3><p><img src="https://news.itsfoss.com/content/images/wordpress/2021/07/open-source-security-illustration.png" alt=""></p><p>既然我们已经澄清了这些有关开源软件安全性的迷思，让我重点展示一下开源软件是如何处理安全问题的。</p><p>换句话说，开源软件在安全性上的优势。</p>',22)),r("p",null,[t[9]||(t[9]=s("请不要忘记，开源软件的优势也是 ",-1)),p(e,{href:"https://itsfoss.com/linux-better-than-windows/"},{default:n(()=>[...t[8]||(t[8]=[s("Linux 比 Windows 更好",-1)])]),_:1}),t[10]||(t[10]=s(" 的一些原因。",-1))]),t[36]||(t[36]=o('<h4 id="更多的眼晴关注开源软件代码" tabindex="-1">更多的眼晴关注开源软件代码 <a class="header-anchor" href="#更多的眼晴关注开源软件代码" aria-label="Permalink to “更多的眼晴关注开源软件代码”">​</a></h4><p>不像专有软件，（对开源软件的）代码访问并不局限于少数几个开发者。</p><p>一些开源项目甚至可能拥有数以万记的开发者可以查看代码、审查它们并标记和修复其中的安全性问题。</p><p>相比闭源软件，这给予了开源项目拥有<strong>快速识别问题并尽快修复它们的能力</strong>的优势。</p><p>不仅仅限于拥有更多的开发者，企业通常也会参与他们所使用的开源项目。当他们这样做的时候，他们也会查阅代码并审查它们。</p><p>这提供了另一条外部审查的途径，而这可能有助于提升开源软件的安全性。</p><p>反之，就闭源软件而言，数量有限的开发者可能并不能找出所有种类的安全问题。而且他们可能需要花费更长的时间来一一修复发现的问题。</p><h4 id="社区决定安全问题的优先级" tabindex="-1">社区决定安全问题的优先级 <a class="header-anchor" href="#社区决定安全问题的优先级" aria-label="Permalink to “社区决定安全问题的优先级”">​</a></h4><p>闭源软件的开发者可能在处理什么问题和什么时候解决问题等方面有某些限制或者优先等级。</p><p>而如果是开源项目，贡献者社区可以自行决定优先级，并自行安排他们想解决的问题以及决定合适修复问题。你不需要依赖于供应商的决定或者按照他们的指示来解决一个安全问题。</p><p>着手处理和修复安全问题的决策在开源软件项目中更加透明和灵活。因此，它可以被证明是更有效的，并为你带来以下三个益处：</p><ul><li>透明度</li><li>不依赖供应商</li><li>更快的安全更新</li></ul><h3 id="开源软件不是防弹的-以下是原因" tabindex="-1">开源软件不是防弹的，以下是原因 <a class="header-anchor" href="#开源软件不是防弹的-以下是原因" aria-label="Permalink to “开源软件不是防弹的，以下是原因”">​</a></h3><p><img src="https://news.itsfoss.com/content/images/wordpress/2021/07/open-source-security-issue.jpg" alt=""></p><p>虽然在某些情况下，开源软件可能在安全性上具有优势，然而仍有一些因素影响它。</p><p>承认这些问题的存在是很重要的，据此，企业或者个人可以就开源软件的安全情况做出更好的决定。</p><h4 id="并无足够的眼睛来审查代码和不确定性" tabindex="-1">并无足够的眼睛来审查代码和不确定性 <a class="header-anchor" href="#并无足够的眼睛来审查代码和不确定性" aria-label="Permalink to “并无足够的眼睛来审查代码和不确定性”">​</a></h4><p>即使开源软件代码可以被全世界的开发者自由访问，<strong>项目没有足够的贡献者/开发者彻底审查开源代码</strong>的可能性仍然存在。</p><p>既如此，我们不能对开源软件的同行审查抱有极高的信心，因为它恰好缺失了这一点。</p><p>开源软件可能“声称”拥有最高的安全性因为它们是开源的。在没有足够的开发者致力于该项目时，这是一种误导。</p><p>同样，我们也无从得知有多少开发者在查看/检查代码，也不知道代码的检查进行到什么程度了。</p>',21)),r("p",null,[t[13]||(t[13]=s("举例而言，",-1)),r("ruby",null,[p(e,{href:"https://www.cve.org/CVERecord?id=CVE-2014-0160"},{default:n(()=>[...t[11]||(t[11]=[s("心脏出血漏洞",-1)])]),_:1}),t[12]||(t[12]=r("rt",null,"Heartbleed",-1))]),t[14]||(t[14]=s(" 是在一个被广泛使用的项目（OpenSSL）中引入了 2 年以后才被发现的。",-1))]),t[37]||(t[37]=o('<h4 id="软件责任与问责" tabindex="-1">软件责任与问责 <a class="header-anchor" href="#软件责任与问责" aria-label="Permalink to “软件责任与问责”">​</a></h4><p>对于个人用户这可能并不重要，但是<strong>开源项目通常并无任何保证</strong>。</p><p>因此，如果一家公司使用它，它们必须自行承担任何由该软件使用造成的数据丢失与损坏。</p><p>这告诉你，没有什么是 100% 安全和没有漏洞的。无论有多少眼睛聚焦在代码上或者贡献者的技术多么精湛，总会存在某种形式的风险，无论是安全风险还是数据丢失。</p><p>这告诉我们一个现实：开源软件并非防弹的。</p><h3 id="开源软件有其更高安全性的优势-但是" tabindex="-1">开源软件有其更高安全性的优势，但是... <a class="header-anchor" href="#开源软件有其更高安全性的优势-但是" aria-label="Permalink to “开源软件有其更高安全性的优势，但是...”">​</a></h3><p>就安全性而言没有什么优胜者。不论是闭源还是开源，当涉及安全问题时都适用同一套原则。</p><p>有很多外部因素可以影响软件安全性，而<strong>其中很多因素并不依赖于源代码</strong>。</p><p>必须以某种形式监控代码，以保证安全。</p><p>是的，<strong>开源道路提供了闭源软件所不具备的优势</strong>，但是这并不意味着开源软件是防弹的。</p><p><em>你对开源软件安全状况有何思考？你又是否认为开源软件比专有软件解决方案更好呢？</em></p><p>提前感谢你在下面的评论中提出的宝贵意见。</p><hr>',13)),r("p",null,[t[16]||(t[16]=s("via: ",-1)),p(e,{href:"https://news.itsfoss.com/open-source-software-security/"},{default:n(()=>[...t[15]||(t[15]=[s("https://news.itsfoss.com/open-source-software-security/",-1)])]),_:1})]),r("p",null,[t[21]||(t[21]=s("作者：",-1)),p(e,{href:"https://news.itsfoss.com/author/ankush/"},{default:n(()=>[...t[17]||(t[17]=[s("Ankush Das",-1)])]),_:1}),t[22]||(t[22]=s(" 选题：",-1)),p(e,{href:"https://github.com/lujun9972"},{default:n(()=>[...t[18]||(t[18]=[s("lujun9972",-1)])]),_:1}),t[23]||(t[23]=s(" 译者：",-1)),p(e,{href:"https://github.com/CanYellow"},{default:n(()=>[...t[19]||(t[19]=[s("CanYellow",-1)])]),_:1}),t[24]||(t[24]=s(" 校对：",-1)),p(e,{href:"https://github.com/wxy"},{default:n(()=>[...t[20]||(t[20]=[s("wxy",-1)])]),_:1})]),r("p",null,[t[27]||(t[27]=s("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[25]||(t[25]=[s("LCTT",-1)])]),_:1}),t[28]||(t[28]=s(" 原创编译，",-1)),p(e,{href:"https://linux.cn/"},{default:n(()=>[...t[26]||(t[26]=[s("Linux中国",-1)])]),_:1}),t[29]||(t[29]=s(" 荣誉推出",-1))])])}const C=l(u,[["render",f]]);export{S as __pageData,C as default};
